-- Тема 17: 35 вопросов в инженерном стиле (133 исправлений), прежние версии в question_archive (миграция 108), ключи не меняются.
-- Источник: scripts/questions/109_style_topic17.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Чем физическая резервная копия отличается от логической (дампа)?', NULL, NULL, NULL, 'У вас есть копия файлов кластера и дамп pg_dump. Чем будет отличаться восстановление из них?'),
        ('question', 'Нужно перенести одну базу на сервер с другой основной версией PostgreSQL. Что подходит?', NULL, NULL, NULL, 'Нужно перенести одну базу с PostgreSQL 15 на PostgreSQL 16. Какой способ подходит?'),
        ('question', 'Мешает ли работающий pg_dump другим сеансам при работе с выгружаемыми таблицами?', NULL, NULL, NULL, 'pg_dump удерживает блокировку выгружаемой таблицы. Как она влияет на чтение, запись и DDL, если других конфликтующих блокировок и очереди ожидания нет?'),
        ('question', 'Чем горячее физическое резервное копирование файлов кластера отличается от холодного?', NULL, NULL, NULL, 'Сервер продолжает принимать изменения, остановить PostgreSQL нельзя. Как создать восстанавливаемую физическую копию?'),
        ('question', 'Как в PostgreSQL 16 называется функция начала низкоуровневого резервного копирования (раньше pg_start_backup)?', NULL, NULL, NULL, 'Обновляете скрипт резервного копирования для PostgreSQL 16. Какая SQL-функция заменила pg_start_backup?'),
        ('question', 'Что делает в PostgreSQL команда ALTER DATABASE … BEGIN BACKUP?', NULL, NULL, NULL, 'Коллега предлагает начать горячее копирование PostgreSQL 16 командой ALTER DATABASE BEGIN BACKUP. Что произойдёт?'),
        ('question', 'Что важно при низкоуровневом копировании через pg_backup_start в PostgreSQL 16?', NULL, NULL, NULL, 'Скрипт вызвал pg_backup_start и копирует файлы кластера. Как он должен завершить этот цикл резервного копирования?'),
        ('question', 'Вызов выполняется на основном сервере (wal_level = replica). Допишите вызов, чтобы копирование началось сразу, с немедленной контрольной точкой:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```', NULL, NULL, NULL, 'На основном сервере PostgreSQL 16 задан wal_level = replica. Допишите вызов, чтобы перед началом копирования контрольная точка выполнилась ускоренно:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```'),
        ('question', 'Что нужно для восстановления кластера на выбранный момент после окончания базовой копии (PITR)?', NULL, NULL, NULL, 'Горячая базовая копия завершилась в 02:00. После ошибочного удаления данных нужно восстановить весь кластер на 14:30 того же дня. Какой комплект нужен?'),
        ('question', 'Кластер подготовлен к восстановлению на момент времени: развёрнута базовая копия, сделанная раньше этого момента, и настроено получение нужных журналов. Допишите параметр, чтобы восстановить кластер на состояние 14:30 10 октября:
```
___ = ''2026-10-10 14:30:00+03''
```', NULL, NULL, NULL, 'Базовая копия завершена до 14:30 10 октября 2026 года. Восстановление из архива подготовлено, нужный WAL доступен. Допишите временную цель:
```
___ = ''2026-10-10 14:30:00+03''
```'),
        ('question', 'Что по умолчанию делает сервер, достигнув целевой точки восстановления?', NULL, NULL, NULL, 'При PITR сервер достиг заданной цели. hot_standby включён, recovery_target_action не меняли. Что произойдёт?'),
        ('question', 'Можно ли при PITR из горячей базовой копии выбрать цель раньше окончания её создания?', NULL, NULL, NULL, 'Горячая копия создавалась с 01:00 до 02:00. Можно ли с её помощью выполнить PITR на 01:30?'),
        ('question', 'Почему высокий buffer hit ratio не означает, что остальные блоки читались с диска?', NULL, NULL, NULL, 'По pg_stat_database доля попаданий в буферный кеш равна 95%. Коллега считает, что остальные 5% обращений читали данные с накопителя. Почему этот вывод неверен?'),
        ('question', 'Чем опасны сеансы в состоянии idle in transaction при настройках по умолчанию?', NULL, NULL, NULL, 'Приложение выполнило BEGIN и обновило одну строку обычной таблицы. Затем перестало отправлять команды, сеанс остался idle in transaction. Тайм-ауты имеют значения по умолчанию. Какие последствия возможны?'),
        ('question', 'Какие системы используют для мониторинга PostgreSQL?', NULL, NULL, NULL, 'Нужно постоянно собирать метрики PostgreSQL, хранить историю и настраивать оповещения. Какие два решения подходят как основа такой системы?'),
        ('question', 'Какая функция показывает, какие процессы блокируют данный процесс?', NULL, NULL, NULL, 'В pg_stat_activity запрос с PID 4321 ждёт блокировку. Какой функцией получить PID процессов, мешающих ему продолжить работу?'),
        ('question', 'Какое значение synchronous_commit гарантирует, что после фиксации изменения уже видны запросам на синхронной реплике?', NULL, NULL, NULL, 'Настроена одна синхронная физическая реплика. После подтверждения COMMIT приложение запускает на ней SELECT с новым снимком. Какое значение synchronous_commit гарантирует, что WAL этой транзакции уже применён?'),
        ('question', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', NULL, NULL, NULL, 'Настроена одна синхронная реплика. При synchronous_commit = remote_write клиент получил успешный COMMIT. Что к этому моменту гарантировано на реплике?'),
        ('question', 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику при настроенной синхронной репликации?', NULL, NULL, NULL, 'Синхронная реплика настроена, но перестала присылать подтверждения WAL. Какие три значения synchronous_commit заставят COMMIT ждать её ответа?'),
        ('question', 'Допишите команду, чтобы не ждать записи журнала только для текущей транзакции:
```
BEGIN;
SET ___ synchronous_commit = off;
```', NULL, NULL, NULL, 'Отключите ожидание надёжной записи WAL при COMMIT для текущей транзакции. После её завершения настройка сеанса должна восстановиться:
```
BEGIN;
SET ___ synchronous_commit = off;
```'),
        ('question', 'Что верно для свойств ACID?', NULL, NULL, NULL, 'Платёжная транзакция меняет два баланса, настройки надёжности штатные. Что верно при полном откате этой транзакции или сбое сервера после успешного COMMIT?'),
        ('question', 'Какой механизм обеспечивает стойкость (D в ACID) в PostgreSQL?', NULL, NULL, NULL, 'COMMIT успешно завершился при synchronous_commit = on и fsync = on. Сервер аварийно остановился до записи всех изменённых страниц обычной журналируемой таблицы. Что позволит восстановить подтверждённые изменения?'),
        ('question', 'Что будет с таблицей, созданной внутри транзакции, если выполнить ROLLBACK?', NULL, NULL, NULL, 'Выполнили BEGIN, создали новую таблицу командой CREATE TABLE, затем выполнили ROLLBACK. Что станет с таблицей?'),
        ('question', 'Какую из этих команд нельзя выполнить внутри явного блока транзакции (таблица t(id integer) существует, имена demo и t_copy свободны)?', NULL, NULL, NULL, 'В базе есть таблица t(id integer). Имена demo и t_copy свободны, необходимые права есть. Вы выполнили BEGIN. Какая команда запрещена внутри этого блока?'),
        ('question', 'Уменьшится ли размер файла таблицы на диске после DELETE и VACUUM?', NULL, NULL, NULL, 'Удалили часть строк, выполнили COMMIT, затем обычный VACUUM без FULL. Что обычно произойдёт с местом в файле таблицы?'),
        ('question', 'Что нужно учитывать, запуская VACUUM FULL для большой таблицы?', NULL, NULL, NULL, 'Планируете VACUUM FULL большой таблицы. Что нужно учесть для доступа к таблице и свободного места?'),
        ('question', 'Как быстрее всего освободить место, если удалить нужно все строки таблицы?', NULL, NULL, NULL, 'Нужно очистить таблицу целиком и вернуть место ОС. Блокировать доступ разрешено; ссылок из других таблиц и DELETE-триггеров нет. Какую команду выбрать?'),
        ('question', 'Чем общий план подготовленного оператора отличается от частного?', NULL, NULL, NULL, 'Один и тот же подготовленный запрос с одним значением параметра выбирает несколько строк, а с другим — половину таблицы. Почему частный план может оказаться эффективнее общего?'),
        ('question', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', NULL, NULL, NULL, 'Новый подготовленный запрос с параметрами выполняют при plan_cache_mode = auto. DDL и ANALYZE между вызовами нет. Как сервер выбирает между частным и общим планом?'),
        ('question', 'Как автоматически обновляется статистика обычной постоянной таблицы при включённой автоочистке?', NULL, NULL, NULL, 'В обычной постоянной таблице изменилось много строк. Автоочистка включена. Как без ручных команд обновится статистика планировщика?'),
        ('question', 'Зачем нужна команда CREATE STATISTICS?', NULL, NULL, NULL, 'Запрос отбирает строки по city и zip одновременно. Значения столбцов связаны, а оценка числа строк неверна. Что сделает CREATE STATISTICS для этих столбцов?'),
        ('question', 'Допишите команду, чтобы после ANALYZE планировщик учитывал зависимость почтового индекса от города:
```
CREATE STATISTICS addr_stats (___) ON city, zip FROM addresses;
```', NULL, NULL, NULL, 'В addresses каждый zip соответствует одному city. Запрос фильтрует оба столбца равенствами константам, а планировщик занижает число строк. Допишите вид статистики для этой зависимости; затем будет выполнен ANALYZE:
```
CREATE STATISTICS addr_stats (___) ON city, zip FROM addresses;
```'),
        ('question', 'Какую блокировку строки берёт команда DELETE?', NULL, NULL, NULL, 'Транзакция выполнила DELETE FROM t WHERE id = 1 и удалила найденную строку, но ещё не завершилась. Какой режим блокировки она удерживает на этой строке?'),
        ('question', 'Чем блокировка FOR SHARE отличается от FOR KEY SHARE для действий других транзакций?', NULL, NULL, NULL, 'В t первичный ключ id, других уникальных индексов нет. A прочитала строку с FOR SHARE и осталась открытой. B обновляет её неключевой столбец. Чем ситуация отличается от случая, когда A использует FOR KEY SHARE?'),
        ('option', 'У вас есть копия файлов кластера и дамп pg_dump. Чем будет отличаться восстановление из них?', 'Разницы нет, это два названия одного и того же', 'Обе восстанавливают выполнением команд SQL', 'Это принципиально разные механизмы.', 'Копию файлов командами SQL не восстановить: её разворачивают как файлы кластера.'),
        ('option', 'У вас есть копия файлов кластера и дамп pg_dump. Чем будет отличаться восстановление из них?', 'Физическая — копия файлов и WAL, логическая — команды SQL', 'Копию файлов разворачивают как есть, дамп — средствами SQL', 'Физическая — копия файлов кластера и журналов WAL, логическая — команды SQL для воссоздания объектов. Поэтому физическая восстанавливается быстро, а при наличии архива WAL — и на любой момент после окончания её создания; логическая гибче.', 'Копию файлов кладут в каталог кластера и при необходимости применяют к ней WAL; дамп загружают через psql или pg_restore.'),
        ('option', 'У вас есть копия файлов кластера и дамп pg_dump. Чем будет отличаться восстановление из них?', 'Логический дамп восстанавливают воспроизведением WAL', 'Копию файлов — средствами SQL, дамп разворачивают как есть', 'Дамп состоит из команд SQL или архива pg_dump, а WAL для него не применяется.', 'Наоборот: средствами SQL восстанавливают дамп, а копию файлов разворачивают как есть.'),
        ('option', 'У вас есть копия файлов кластера и дамп pg_dump. Чем будет отличаться восстановление из них?', 'Физическая копия содержит команды SQL, логическая — файлы', 'Обе разворачивают как есть, заменяя файлы PGDATA', 'Наоборот: физическая — копия файлов кластера, логическая — команды SQL.', 'Дамп не содержит файлов кластера: это команды SQL или архив pg_dump для воссоздания объектов.'),
        ('explanation', 'У вас есть копия файлов кластера и дамп pg_dump. Чем будет отличаться восстановление из них?', NULL, NULL, 'Физическая копия сохраняет файлы кластера, логическая — определения объектов и данные для их воссоздания средствами SQL.', 'Физическую копию разворачивают как файлы кластера и при необходимости применяют к ней WAL, так её можно довести до нужного момента. Логическую восстанавливают средствами SQL: скрипт через psql, архив через pg_restore; так можно перенести и отдельные объекты.'),
        ('option', 'Нужно перенести одну базу с PostgreSQL 15 на PostgreSQL 16. Какой способ подходит?', 'Дамп pg_dump', 'Выгрузить pg_dump и загрузить дамп', 'Для команд SQL двоичная совместимость не нужна.', 'pg_dump создаёт SQL-скрипт или архив для pg_restore. Восстановление идёт на логическом уровне, поэтому двоичная совместимость файлов не нужна. Загрузка в более старую основную версию не гарантируется.'),
        ('option', 'Нужно перенести одну базу с PostgreSQL 15 на PostgreSQL 16. Какой способ подходит?', 'Копирование каталога базы из PGDATA/base', 'Перенести каталог базы из PGDATA/base', NULL, NULL),
        ('option', 'Нужно перенести одну базу с PostgreSQL 15 на PostgreSQL 16. Какой способ подходит?', 'Физическая реплика', 'Создать физическую реплику этой базы', 'Физическая репликация требует той же основной версии.', 'Физическая репликация работает между серверами одной основной версии и копирует кластер целиком.'),
        ('option', 'Нужно перенести одну базу с PostgreSQL 15 на PostgreSQL 16. Какой способ подходит?', 'Базовая копия pg_basebackup', 'Восстановить базовую копию pg_basebackup', 'Физическая копия восстанавливается только на той же основной версии и архитектуре, к тому же только целиком.', 'Физическая копия восстанавливается целиком и на той же основной версии.'),
        ('explanation', 'Нужно перенести одну базу с PostgreSQL 15 на PostgreSQL 16. Какой способ подходит?', NULL, NULL, 'pg_dump выгружает одну базу на логическом уровне, поэтому её можно перенести на совместимую другую основную версию без копирования физических файлов.', 'pg_dump выгружает одну базу на логическом уровне, поэтому её можно загрузить на более новую основную версию без копирования физических файлов.'),
        ('option', 'pg_dump удерживает блокировку выгружаемой таблицы. Как она влияет на чтение, запись и DDL, если других конфликтующих блокировок и очереди ожидания нет?', 'Никак не мешает: блокировок он не берёт', 'Чтение, запись и DDL с ACCESS EXCLUSIVE проходят', 'Блокировки ACCESS SHARE конфликтуют с командами, которым нужна ACCESS EXCLUSIVE.', 'pg_dump держит ACCESS SHARE, а она конфликтует с ACCESS EXCLUSIVE: DROP TABLE и большинство форм ALTER TABLE будут ждать.'),
        ('option', 'pg_dump удерживает блокировку выгружаемой таблицы. Как она влияет на чтение, запись и DDL, если других конфликтующих блокировок и очереди ожидания нет?', 'Чтение и запись идут, DDL с ACCESS EXCLUSIVE ждёт', 'Чтение и запись проходят, DDL с ACCESS EXCLUSIVE ждёт', NULL, NULL),
        ('option', 'pg_dump удерживает блокировку выгружаемой таблицы. Как она влияет на чтение, запись и DDL, если других конфликтующих блокировок и очереди ожидания нет?', 'Блокирует всю базу на запись до конца выгрузки дампа', 'Чтение проходит, запись и DDL с ACCESS EXCLUSIVE ждут', 'Изменять данные можно: pg_dump читает согласованный снимок.', 'Запись не конфликтует с ACCESS SHARE у pg_dump: блокировка INSERT, UPDATE и DELETE с ней совместима.'),
        ('option', 'pg_dump удерживает блокировку выгружаемой таблицы. Как она влияет на чтение, запись и DDL, если других конфликтующих блокировок и очереди ожидания нет?', 'Останавливает автоочистку во всём кластере', 'Чтение, запись и DDL с ACCESS EXCLUSIVE ждут', 'Автоочистку он не останавливает, хотя его долгая транзакция удерживает горизонт очистки.', 'Чтение и запись не конфликтуют с ACCESS SHARE у pg_dump: она мешает лишь ACCESS EXCLUSIVE.'),
        ('explanation', 'pg_dump удерживает блокировку выгружаемой таблицы. Как она влияет на чтение, запись и DDL, если других конфликтующих блокировок и очереди ожидания нет?', NULL, NULL, 'pg_dump удерживает ACCESS SHARE: обычные чтение и запись продолжаются, а операции, требующие ACCESS EXCLUSIVE на выгружаемых таблицах, ждут.', 'ACCESS SHARE у pg_dump напрямую конфликтует с ACCESS EXCLUSIVE, но совместима с блокировками обычного чтения и изменения данных. Отдельно ожидающий DDL может задержать последующие запросы в очереди.'),
        ('option', 'Сервер продолжает принимать изменения, остановить PostgreSQL нельзя. Как создать восстанавливаемую физическую копию?', 'Горячая копия восстанавливается без использования WAL', 'Копировать работающий кластер без сохранения WAL', 'Для согласования горячей копии нужен WAL: он может лежать в самой копии или поступать из отдельного архива.', 'Файлы копируются в разные моменты и получаются несогласованными; без WAL за время копирования их не восстановить.'),
        ('option', 'Сервер продолжает принимать изменения, остановить PostgreSQL нельзя. Как создать восстанавливаемую физическую копию?', 'Делается на работающем сервере, нужен WAL за это время', 'Снять горячую копию и сохранить необходимый WAL', NULL, NULL),
        ('option', 'Сервер продолжает принимать изменения, остановить PostgreSQL нельзя. Как создать восстанавливаемую физическую копию?', 'Горячее делается при остановленном сервере', 'Снять холодную копию без остановки PostgreSQL', 'Это холодное копирование.', 'Холодную копию по определению делают на остановленном сервере, а здесь остановить его нельзя.'),
        ('option', 'Сервер продолжает принимать изменения, остановить PostgreSQL нельзя. Как создать восстанавливаемую физическую копию?', 'Холодной копии нужен архив журналов WAL', 'Скопировать файлы после CHECKPOINT без сохранения WAL', 'После штатной остановки внешний архив WAL не нужен, но каталог pg_wal сохраняют в составе холодной копии.', 'После CHECKPOINT сервер продолжает менять файлы, так что копия всё равно несогласованна и без WAL не восстановится.'),
        ('explanation', 'Сервер продолжает принимать изменения, остановить PostgreSQL нельзя. Как создать восстанавливаемую физическую копию?', NULL, NULL, 'Холодная копия проще, но требует остановки сервера.', 'Горячую копию делают на работающем сервере штатной процедурой: pg_basebackup или низкоуровневым API pg_backup_start и pg_backup_stop; WAL за время копирования приводит её к согласованному состоянию. Холодная копия проще, но требует остановки сервера.'),
        ('option', 'Коллега предлагает начать горячее копирование PostgreSQL 16 командой ALTER DATABASE BEGIN BACKUP. Что произойдёт?', 'Такой команды нет, это синтаксис Oracle', 'Завершится синтаксической ошибкой', 'В PostgreSQL низкоуровневое копирование начинают функцией pg_backup_start.', 'Такой команды в PostgreSQL нет, это синтаксис Oracle; низкоуровневое копирование начинают функцией pg_backup_start.'),
        ('option', 'Коллега предлагает начать горячее копирование PostgreSQL 16 командой ALTER DATABASE BEGIN BACKUP. Что произойдёт?', 'Запрещает запись в базу до конца копирования', 'Запретит запись в базу до конца копирования', NULL, NULL),
        ('option', 'Коллега предлагает начать горячее копирование PostgreSQL 16 командой ALTER DATABASE BEGIN BACKUP. Что произойдёт?', 'Создаёт базовую копию в каталоге по умолчанию', 'Создаст базовую копию в каталоге по умолчанию', NULL, NULL),
        ('option', 'Коллега предлагает начать горячее копирование PostgreSQL 16 командой ALTER DATABASE BEGIN BACKUP. Что произойдёт?', 'Переводит базу в режим горячего копирования', 'Переведёт базу в режим горячего копирования', NULL, NULL),
        ('option', 'Скрипт вызвал pg_backup_start и копирует файлы кластера. Как он должен завершить этот цикл резервного копирования?', 'Между вызовами к серверу нельзя подключаться другим сеансам', 'Закрыть другие соединения до вызова pg_backup_stop', 'Ограничения на подключения нет.', 'Другие соединения копированию не мешают, закрывать их не нужно.'),
        ('option', 'Скрипт вызвал pg_backup_start и копирует файлы кластера. Как он должен завершить этот цикл резервного копирования?', 'Сеанс с pg_backup_start должен жить до pg_backup_stop', 'Вызвать pg_backup_stop в том же открытом соединении', 'Сеанс, вызвавший pg_backup_start, должен оставаться открытым до pg_backup_stop: если соединение прервётся, копирование будет отменено.', 'Соединение, вызвавшее pg_backup_start, сохраняют до завершения pg_backup_stop: если оно прервётся, копирование будет отменено.'),
        ('option', 'Скрипт вызвал pg_backup_start и копирует файлы кластера. Как он должен завершить этот цикл резервного копирования?', 'Сервер нужно перевести в режим без записи', 'Запретить запись на сервере до вызова pg_backup_stop', 'Сервер продолжает работать как обычно.', 'Сервер продолжает работать как обычно, запись не запрещают.'),
        ('option', 'Скрипт вызвал pg_backup_start и копирует файлы кластера. Как он должен завершить этот цикл резервного копирования?', 'pg_backup_stop можно вызвать из любого другого сеанса', 'Закрыть исходное соединение и открыть новое для stop', 'Копирование не монопольное и привязано к сеансу, который его начал.', 'Разрыв исходного соединения отменяет режим копирования, pg_backup_stop из нового соединения его не завершит.'),
        ('explanation', 'Скрипт вызвал pg_backup_start и копирует файлы кластера. Как он должен завершить этот цикл резервного копирования?', NULL, NULL, 'Сеанс сохраняют от pg_backup_start до pg_backup_stop; разрыв соединения отменяет режим копирования. Возвращённые pg_backup_stop содержимое backup_label и непустой tablespace_map сохраняют без изменений в корне резервной копии.', 'Соединение сохраняют до завершения pg_backup_stop: разрыв отменяет режим резервирования. Из результата pg_backup_stop записывают backup_label и непустой tablespace_map в корень копии без изменения содержимого.'),
        ('explanation', 'На основном сервере PostgreSQL 16 задан wal_level = replica. Допишите вызов, чтобы перед началом копирования контрольная точка выполнилась ускоренно:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```', NULL, NULL, 'fast => true требует немедленной контрольной точки; false допускает растянутую запись перед началом копирования.', 'fast => true ускоряет контрольную точку. Функция возвращает управление после её завершения; это может увеличить нагрузку на ввод-вывод.'),
        ('option', 'Горячая базовая копия завершилась в 02:00. После ошибочного удаления данных нужно восстановить весь кластер на 14:30 того же дня. Какой комплект нужен?', 'Базовая копия и непрерывный архив WAL до цели', 'Базовая копия и непрерывный WAL до 14:30', 'Нужны базовая копия и непрерывный архив WAL от её начала до нужного момента: журнал применяется к копии до целевой точки.', 'Нужна базовая копия и непрерывная цепочка WAL от стартовой позиции этой копии до 14:30: журнал применяется к копии до целевой точки.'),
        ('explanation', 'Горячая базовая копия завершилась в 02:00. После ошибочного удаления данных нужно восстановить весь кластер на 14:30 того же дня. Какой комплект нужен?', NULL, NULL, 'Для PITR нужна подходящая базовая копия и непрерывная цепочка WAL от её начальной позиции до цели восстановления.', 'Цепочка WAL должна быть непрерывной от стартовой позиции, необходимой этой копии, до 14:30. WAL применяют к физической копии, не к pg_dump.'),
        ('option', 'При PITR сервер достиг заданной цели. hot_standby включён, recovery_target_action не меняли. Что произойдёт?', 'Удаляет использованные сегменты архива журналов', NULL, 'Архив сервер не трогает.', 'Достижение цели само по себе не удаляет архив WAL.'),
        ('option', 'Горячая копия создавалась с 01:00 до 02:00. Можно ли с её помощью выполнить PITR на 01:30?', 'Нет: цель должна быть позже конца копирования', 'Нет, копия ещё не достигнет согласованного состояния', 'Целевая точка должна быть после окончания копирования: раньше этого момента копия ещё несогласованна; нужна более ранняя копия.', 'Из этой копии recovery нельзя остановить раньше конца резервирования, когда она становится согласованной: для 01:30 нужна более ранняя копия.'),
        ('option', 'Горячая копия создавалась с 01:00 до 02:00. Можно ли с её помощью выполнить PITR на 01:30?', 'Да, если указать в настройках recovery_target_lsn', 'Да, если вместо времени указать recovery_target_lsn', NULL, NULL),
        ('option', 'Горячая копия создавалась с 01:00 до 02:00. Можно ли с её помощью выполнить PITR на 01:30?', 'Да, если восстанавливать отдельную базу', 'Да, если восстанавливать одну выбранную базу кластера', NULL, NULL),
        ('option', 'Горячая копия создавалась с 01:00 до 02:00. Можно ли с её помощью выполнить PITR на 01:30?', 'Да, на любой момент, который есть в архиве', 'Да, если в архиве есть WAL за весь этот промежуток', 'Журнал проигрывается вперёд от начала копии, а остановиться можно только после достижения согласованности.', 'Журнал проигрывается вперёд от начала копии, но остановиться можно лишь после достижения согласованности.'),
        ('explanation', 'Горячая копия создавалась с 01:00 до 02:00. Можно ли с её помощью выполнить PITR на 01:30?', NULL, NULL, 'Горячая копия становится согласованной лишь после воспроизведения необходимого WAL до конца копирования; для более ранней цели нужна более ранняя копия.', 'Из этой копии нельзя остановить recovery раньше достижения согласованности в конце резервирования. Для 01:30 нужна более ранняя копия.'),
        ('explanation', 'По pg_stat_database доля попаданий в буферный кеш равна 95%. Коллега считает, что остальные 5% обращений читали данные с накопителя. Почему этот вывод неверен?', NULL, NULL, 'Счётчики PostgreSQL, включая blks_read и pg_stat_io, считают обращения к ОС и не отличают чтение с накопителя от чтения из кеша ОС. Реальные обращения к устройствам смотрят средствами ОС, например iostat.', 'blks_read считает чтения блоков вне буферного кеша PostgreSQL: запрос к ОС мог обслужить её кеш. Счётчики чтения в pg_stat_io тоже не показывают, дошло ли чтение до накопителя. Реальную активность устройств проверяют средствами ОС, например iostat.'),
        ('option', 'Приложение выполнило BEGIN и обновило одну строку обычной таблицы. Затем перестало отправлять команды, сеанс остался idle in transaction. Тайм-ауты имеют значения по умолчанию. Какие последствия возможны?', 'Они автоматически откатываются через минуту', 'Через минуту сервер откатит UPDATE и освободит блокировки', 'По умолчанию не откатываются; для этого есть idle_in_transaction_session_timeout.', 'По умолчанию idle_in_transaction_session_timeout = 0, сеанс никто не прерывает. Если тайм-аут задан, сервер завершит сеанс, а транзакция откатится.'),
        ('option', 'Приложение выполнило BEGIN и обновило одну строку обычной таблицы. Затем перестало отправлять команды, сеанс остался idle in transaction. Тайм-ауты имеют значения по умолчанию. Какие последствия возможны?', 'Они ничем не опасны для сервера', 'До следующей команды сервер временно освободит блокировки', 'Это частая причина разрастания таблиц и ожиданий блокировок.', 'Блокировки держатся до конца транзакции, паузы между командами их не снимают.'),
        ('option', 'Приложение выполнило BEGIN и обновило одну строку обычной таблицы. Затем перестало отправлять команды, сеанс остался idle in transaction. Тайм-ауты имеют значения по умолчанию. Какие последствия возможны?', 'Они потребляют много процессорного времени сервера', 'UPDATE продолжит выполняться и расходовать процессор', 'Бездействующий сеанс процессор почти не нагружает.', 'UPDATE уже выполнен, сеанс ждёт следующей команды и процессор почти не нагружает.'),
        ('option', 'Приложение выполнило BEGIN и обновило одну строку обычной таблицы. Затем перестало отправлять команды, сеанс остался idle in transaction. Тайм-ауты имеют значения по умолчанию. Какие последствия возможны?', 'Держат блокировки и могут удерживать горизонт', 'Блокировки сохранятся, очистка может отставать', 'Они удерживают блокировки и могут удерживать горизонт очистки: таблицы растут, а другие сеансы ждут блокировок.', 'До завершения транзакции сохраняется блокировка изменённой строки. Номер открытой пишущей транзакции может задерживать очистку старых версий; другие сеансы ждут, если запрашивают несовместимые блокировки.'),
        ('option', 'Нужно постоянно собирать метрики PostgreSQL, хранить историю и настраивать оповещения. Какие два решения подходят как основа такой системы?', 'pgbench с ключом --progress', NULL, 'Это утилита нагрузочного тестирования; --progress показывает ход теста, а не мониторит сервер.', 'Это утилита нагрузочного тестирования: --progress показывает ход теста, а не организует постоянный мониторинг с историей и оповещениями.'),
        ('option', 'В pg_stat_activity запрос с PID 4321 ждёт блокировку. Какой функцией получить PID процессов, мешающих ему продолжить работу?', '`pg_blocking_pids(pid)`', '`pg_blocking_pids(4321)`', NULL, NULL),
        ('option', 'В pg_stat_activity запрос с PID 4321 ждёт блокировку. Какой функцией получить PID процессов, мешающих ему продолжить работу?', '`pg_cancel_backend(pid)`', '`pg_cancel_backend(4321)`', NULL, NULL),
        ('option', 'Настроена одна синхронная реплика. При synchronous_commit = remote_write клиент получил успешный COMMIT. Что к этому моменту гарантировано на реплике?', 'Реплика получила записи и передала их ОС', 'WAL записан в файловую систему реплики', 'Реплика получила записи и передала их ОС, но на диск они могли ещё не попасть: при сбое ОС реплики сохранность данных на ней не гарантируется.', 'Реплика записала WAL в файловую систему, но на носитель он мог ещё не попасть: при сбое ОС реплики сохранность на ней не гарантируется.'),
        ('option', 'Настроена одна синхронная реплика. При synchronous_commit = remote_write клиент получил успешный COMMIT. Что к этому моменту гарантировано на реплике?', 'Фиксация не ждёт синхронную реплику', 'Подтверждение реплики ещё не получено', 'Это значения local и off.', 'При remote_write COMMIT ждёт подтверждения реплики, поэтому оно уже получено.'),
        ('option', 'Настроена одна синхронная реплика. При synchronous_commit = remote_write клиент получил успешный COMMIT. Что к этому моменту гарантировано на реплике?', 'Записи надёжно сброшены на диск синхронной реплики', 'WAL гарантированно сброшен на носитель', 'Это значение on.', 'Сброс на носитель реплики гарантирует значение on.'),
        ('option', 'Настроена одна синхронная реплика. При synchronous_commit = remote_write клиент получил успешный COMMIT. Что к этому моменту гарантировано на реплике?', 'Записи уже применены на реплике и видны запросам', 'Изменения применены процессом recovery', 'Это значение remote_apply.', 'Применение на реплике гарантирует значение remote_apply.'),
        ('option', 'Платёжная транзакция меняет два баланса, настройки надёжности штатные. Что верно при полном откате этой транзакции или сбое сервера после успешного COMMIT?', 'Стойкость: зафиксированные изменения переживают сбой', 'Стойкость: подтверждённые изменения сохранятся после сбоя', 'Это обеспечивает журнал предзаписи.', 'Успешный COMMIT означает, что WAL транзакции надёжно записан: после сбоя изменения восстановятся.'),
        ('option', 'Платёжная транзакция меняет два баланса, настройки надёжности штатные. Что верно при полном откате этой транзакции или сбое сервера после успешного COMMIT?', 'Атомарность: транзакция применяется целиком или никак', 'Атомарность: при полном откате отменятся оба изменения', 'Частично выполненной транзакции не бывает.', 'При полном откате транзакции ни одно из её изменений балансов не фиксируется. Откат к точке сохранения отменяет лишь изменения после неё.'),
        ('option', 'Платёжная транзакция меняет два баланса, настройки надёжности штатные. Что верно при полном откате этой транзакции или сбое сервера после успешного COMMIT?', 'Согласованность: данные на всех репликах одинаковы', 'Согласованность: каждая реплика подтвердит оба изменения', 'Речь о соблюдении ограничений целостности в одной базе, а не о репликах.', 'Согласованность относится к заданным ограничениям и инвариантам данных, а не к подтверждению каждой репликой.'),
        ('option', 'Платёжная транзакция меняет два баланса, настройки надёжности штатные. Что верно при полном откате этой транзакции или сбое сервера после успешного COMMIT?', 'Изолированность: транзакции выполняются строго по очереди', 'Изолированность: другие транзакции начнутся после платежа', 'Транзакции выполняются параллельно, а уровень изоляции определяет, какие аномалии допустимы.', 'Транзакции выполняются параллельно, а уровень изоляции определяет, какие аномалии между ними допустимы.'),
        ('option', 'COMMIT успешно завершился при synchronous_commit = on и fsync = on. Сервер аварийно остановился до записи всех изменённых страниц обычной журналируемой таблицы. Что позволит восстановить подтверждённые изменения?', 'Буферный кеш', 'Содержимое shared_buffers, сохранённое в оперативной памяти', 'Он в оперативной памяти и при сбое теряется.', 'shared_buffers находится в оперативной памяти и при сбое теряется.'),
        ('option', 'COMMIT успешно завершился при synchronous_commit = on и fsync = on. Сервер аварийно остановился до записи всех изменённых страниц обычной журналируемой таблицы. Что позволит восстановить подтверждённые изменения?', 'Запись грязных буферов при каждой фиксации', 'Сброс всех изменённых страниц таблицы при каждом COMMIT', 'Буферы пишутся независимо от фиксации: при контрольной точке, фоновой записью или при вытеснении.', 'COMMIT не требует сброса всех изменённых страниц таблицы. Их могут записать контрольная точка, фоновый процесс или обслуживающий процесс при освобождении буферов.'),
        ('option', 'COMMIT успешно завершился при synchronous_commit = on и fsync = on. Сервер аварийно остановился до записи всех изменённых страниц обычной журналируемой таблицы. Что позволит восстановить подтверждённые изменения?', 'Автоочистка', 'Очистка старых версий строк первым запуском autovacuum', 'Она удаляет неактуальные версии строк.', 'Автоочистка убирает неактуальные версии строк, к восстановлению она не относится.'),
        ('option', 'COMMIT успешно завершился при synchronous_commit = on и fsync = on. Сервер аварийно остановился до записи всех изменённых страниц обычной журналируемой таблицы. Что позволит восстановить подтверждённые изменения?', 'Запись журнала WAL на диск при фиксации', 'Надёжная запись WAL до подтверждения успешного COMMIT', 'После сбоя изменения восстанавливаются по журналу.', 'WAL транзакции сброшен на диск до ответа на COMMIT; после сбоя сервер повторяет изменения по журналу.'),
        ('explanation', 'COMMIT успешно завершился при synchronous_commit = on и fsync = on. Сервер аварийно остановился до записи всех изменённых страниц обычной журналируемой таблицы. Что позволит восстановить подтверждённые изменения?', NULL, NULL, 'Именно поэтому synchronous_commit = off ослабляет стойкость.', 'До подтверждения COMMIT WAL надёжно записан. Если страницы данных ещё не попали на диск, после сбоя сервер восстановит изменения по WAL.'),
        ('option', 'Выполнили BEGIN, создали новую таблицу командой CREATE TABLE, затем выполнили ROLLBACK. Что станет с таблицей?', 'Таблица останется, но будет пустой', 'Таблица сохранится, но добавленные строки исчезнут', 'Таблица не будет создана вовсе.', 'После отката созданной таблицы не останется вовсе, а не одних её строк.'),
        ('option', 'Выполнили BEGIN, создали новую таблицу командой CREATE TABLE, затем выполнили ROLLBACK. Что станет с таблицей?', 'Её не будет: CREATE TABLE транзакционна', 'Созданная в этой транзакции таблица исчезнет', 'CREATE TABLE, как и большинство команд DDL в PostgreSQL, транзакционна; это отличает PostgreSQL от многих других СУБД.', 'CREATE TABLE, как и большинство команд DDL в PostgreSQL, транзакционна: откат отменяет создание таблицы.'),
        ('option', 'Выполнили BEGIN, создали новую таблицу командой CREATE TABLE, затем выполнили ROLLBACK. Что станет с таблицей?', 'ROLLBACK завершится ошибкой из-за выполненного DDL', 'ROLLBACK завершится ошибкой из-за создания таблицы', 'ROLLBACK отменяет и команды DDL, ошибки нет.', 'ROLLBACK отменяет выполненный в этой транзакции CREATE TABLE, ошибки нет.'),
        ('option', 'Выполнили BEGIN, создали новую таблицу командой CREATE TABLE, затем выполнили ROLLBACK. Что станет с таблицей?', 'DDL вообще нельзя выполнять внутри транзакции', 'CREATE TABLE завершится ошибкой внутри транзакции', 'Большинство команд DDL можно выполнять в транзакции и откатывать.', 'CREATE TABLE можно выполнять внутри транзакции и откатывать.'),
        ('option', 'В базе есть таблица t(id integer). Имена demo и t_copy свободны, необходимые права есть. Вы выполнили BEGIN. Какая команда запрещена внутри этого блока?', '`ALTER TABLE t ADD COLUMN note text;`', NULL, 'Форма ADD COLUMN выполняется в транзакции и откатывается; исключением среди форм ALTER TABLE остаётся DETACH PARTITION CONCURRENTLY.', 'Форма ADD COLUMN выполняется в транзакции и откатывается.'),
        ('option', 'Удалили часть строк, выполнили COMMIT, затем обычный VACUUM без FULL. Что обычно произойдёт с местом в файле таблицы?', 'Обычно нет: место остаётся внутри файла', 'Свободное место останется для новых строк этой таблицы', 'Место станет свободным внутри файла, и его используют новые строки этой таблицы; ОС вернётся только пустой хвост файла.', 'Место станет свободным внутри файла, его займут новые строки этой таблицы; ОС может вернуться только пустой хвост файла.'),
        ('option', 'Удалили часть строк, выполнили COMMIT, затем обычный VACUUM без FULL. Что обычно произойдёт с местом в файле таблицы?', 'Обычно да, сразу после выполнения DELETE', 'Освободившиеся страницы сразу перейдут другим таблицам', 'DELETE только помечает версии строк как удалённые.', 'Свободное место остаётся внутри файла этой таблицы, другим таблицам оно не достаётся.'),
        ('option', 'Удалили часть строк, выполнили COMMIT, затем обычный VACUUM без FULL. Что обычно произойдёт с местом в файле таблицы?', 'Обычно да, после следующей контрольной точки', 'Файл уменьшится после следующей контрольной точки', NULL, NULL),
        ('option', 'Удалили часть строк, выполнили COMMIT, затем обычный VACUUM без FULL. Что обычно произойдёт с местом в файле таблицы?', 'Обычно да, VACUUM сжимает файл до размера данных', 'VACUUM уплотнит все страницы и уменьшит файл таблицы', 'VACUUM возвращает ОС только пустые страницы в конце файла, а не сжимает его до размера данных.', 'Обычный VACUUM не перемещает строки между страницами; уплотняет таблицу VACUUM FULL.'),
        ('explanation', 'Удалили часть строк, выполнили COMMIT, затем обычный VACUUM без FULL. Что обычно произойдёт с местом в файле таблицы?', NULL, NULL, 'Вернуть место ОС можно VACUUM FULL или перезаписью таблицы.', 'Обычный VACUUM освобождает место для повторного использования. Он может вернуть ОС пустые страницы в конце файла, но не уплотняет оставшиеся данные. VACUUM FULL переписывает таблицу компактнее и возвращает освободившееся место ОС.'),
        ('option', 'Планируете VACUUM FULL большой таблицы. Что нужно учесть для доступа к таблице и свободного места?', 'Дополнительное место на диске не нужно', 'Чтение доступно; дополнительное место не требуется', 'Новая копия создаётся рядом со старой.', 'Берётся ACCESS EXCLUSIVE, недоступно даже чтение; новая копия создаётся рядом со старой.'),
        ('option', 'Планируете VACUUM FULL большой таблицы. Что нужно учесть для доступа к таблице и свободного места?', 'Таблица блокируется, и нужно место для её копии', 'Доступ блокируется; нужно место для новой копии', 'Таблица полностью блокируется (ACCESS EXCLUSIVE), и нужно свободное место для её новой копии: таблица и индексы перезаписываются заново.', 'Таблица полностью блокируется (ACCESS EXCLUSIVE), а таблица и индексы перезаписываются заново: пока старые файлы не удалены, нужно место и для новых.'),
        ('option', 'Планируете VACUUM FULL большой таблицы. Что нужно учесть для доступа к таблице и свободного места?', 'Индексы после него нужно перестроить вручную', 'Запись доступна; индексы перестраивают вручную', 'Индексы перестраиваются автоматически.', 'Берётся ACCESS EXCLUSIVE, запись недоступна; индексы перестраиваются автоматически.'),
        ('option', 'Планируете VACUUM FULL большой таблицы. Что нужно учесть для доступа к таблице и свободного места?', 'Таблица остаётся доступной для записи', 'Доступ блокируется; новая копия не создаётся', 'Берётся блокировка ACCESS EXCLUSIVE, недоступно даже чтение.', 'Доступ действительно блокируется, но VACUUM FULL как раз создаёт новую копию таблицы.'),
        ('option', 'Нужно очистить таблицу целиком и вернуть место ОС. Блокировать доступ разрешено; ссылок из других таблиц и DELETE-триггеров нет. Какую команду выбрать?', 'Выполнить DELETE без условия', 'Удалить все строки командой DELETE', 'Строки станут мёртвыми, но место на диске не освободится.', 'DELETE помечает версии строк удалёнными, но сам не освобождает место для ОС. Когда старые версии больше не нужны, очистка позволит повторно использовать место и может усечь пустой хвост файла.'),
        ('option', 'Нужно очистить таблицу целиком и вернуть место ОС. Блокировать доступ разрешено; ссылок из других таблиц и DELETE-триггеров нет. Какую команду выбрать?', 'Выполнить TRUNCATE', 'Очистить таблицу командой TRUNCATE', NULL, NULL),
        ('option', 'Нужно очистить таблицу целиком и вернуть место ОС. Блокировать доступ разрешено; ссылок из других таблиц и DELETE-триггеров нет. Какую команду выбрать?', 'Выполнить CHECKPOINT', 'Выполнить контрольную точку CHECKPOINT', NULL, NULL),
        ('option', 'Нужно очистить таблицу целиком и вернуть место ОС. Блокировать доступ разрешено; ссылок из других таблиц и DELETE-триггеров нет. Какую команду выбрать?', 'Выполнить DELETE и ANALYZE', 'Выполнить DELETE и затем ANALYZE', 'ANALYZE обновляет статистику, а не место на диске.', 'ANALYZE обновляет статистику и не заменяет VACUUM.'),
        ('explanation', 'Нужно очистить таблицу целиком и вернуть место ОС. Блокировать доступ разрешено; ссылок из других таблиц и DELETE-триггеров нет. Какую команду выбрать?', NULL, NULL, 'TRUNCATE берёт блокировку ACCESS EXCLUSIVE, но работает быстро.', 'TRUNCATE берёт блокировку ACCESS EXCLUSIVE и заменяет файлы таблицы пустыми; изменение транзакционно, место освобождается после COMMIT.'),
        ('option', 'Один и тот же подготовленный запрос с одним значением параметра выбирает несколько строк, а с другим — половину таблицы. Почему частный план может оказаться эффективнее общего?', 'Частный учитывает значения параметров, общий — нет', 'Частный строится под значения параметров, общий — без них', NULL, NULL),
        ('option', 'Один и тот же подготовленный запрос с одним значением параметра выбирает несколько строк, а с другим — половину таблицы. Почему частный план может оказаться эффективнее общего?', 'Общий учитывает значения параметров, частный — нет', 'Общий строится под значения параметров, частный — без них', NULL, NULL),
        ('explanation', 'Один и тот же подготовленный запрос с одним значением параметра выбирает несколько строк, а с другим — половину таблицы. Почему частный план может оказаться эффективнее общего?', NULL, NULL, 'Частный план учитывает конкретные значения параметров; общий план не зависит от этих значений и может использоваться повторно.', 'Частный план строится под конкретные значения параметров; общий — без них и используется повторно, значения он получает только при выполнении.'),
        ('option', 'Новый подготовленный запрос с параметрами выполняют при plan_cache_mode = auto. DDL и ANALYZE между вызовами нет. Как сервер выбирает между частным и общим планом?', 'После ANALYZE, если общий план стал дешевле частных', 'Ждёт ANALYZE и выбирает план по его результатам', 'ANALYZE лишь делает план недействительным для перестроения, правила перехода он не задаёт.', 'ANALYZE обновляет статистику и может вызвать перепланирование, но не задаёт правило выбора общего плана.'),
        ('option', 'Новый подготовленный запрос с параметрами выполняют при plan_cache_mode = auto. DDL и ANALYZE между вызовами нет. Как сервер выбирает между частным и общим планом?', 'После пяти частных планов, если общий не намного дороже', 'После пяти запусков с частным планом сравнивает затраты', 'После пяти выполнений с частными планами, если общий план не намного дороже их средней стоимости; иначе продолжают строиться частные планы.', 'Первые пять выполнений получают частные планы; затем общий план сравнивается со средней оценкой частных с учётом затрат планирования, переход не обязателен.'),
        ('option', 'Новый подготовленный запрос с параметрами выполняют при plan_cache_mode = auto. DDL и ANALYZE между вызовами нет. Как сервер выбирает между частным и общим планом?', 'Сразу при первом выполнении, если общий план дешевле', 'При первом выполнении сравнивает оба варианта плана', 'Первые пять выполнений используют частные планы.', 'Первые пять выполнений используют частные планы, сравнение начинается после них.'),
        ('option', 'Новый подготовленный запрос с параметрами выполняют при plan_cache_mode = auto. DDL и ANALYZE между вызовами нет. Как сервер выбирает между частным и общим планом?', 'Не переходит, пока не задан режим force_generic_plan', 'Сохраняет частные планы до включения force_generic_plan', 'Переход возможен после пяти выполнений; force_generic_plan включает общий план сразу.', 'Переход возможен после пяти выполнений и без force_generic_plan; этот режим включает общий план сразу.'),
        ('explanation', 'Новый подготовленный запрос с параметрами выполняют при plan_cache_mode = auto. DDL и ANALYZE между вызовами нет. Как сервер выбирает между частным и общим планом?', NULL, NULL, 'При auto сначала выполняются пять частных планов; затем стоимость общего плана сравнивается со средней стоимостью частных с учётом затрат планирования.', 'Для первых пяти выполнений строятся частные планы. Затем оценка общего плана сравнивается со средней оценкой частных с учётом затрат на планирование. Переход на общий план не обязателен.'),
        ('option', 'В обычной постоянной таблице изменилось много строк. Автоочистка включена. Как без ручных команд обновится статистика планировщика?', 'Автоочистка запускает ANALYZE при достижении порога', 'Автоочистка запустит ANALYZE после превышения порога', NULL, NULL),
        ('option', 'Запрос отбирает строки по city и zip одновременно. Значения столбцов связаны, а оценка числа строк неверна. Что сделает CREATE STATISTICS для этих столбцов?', 'Посмотреть собранную статистику по таблице', 'Покажет собранную статистику по таблице', 'Для этого есть pg_stats, pg_stats_ext и накопительные представления pg_stat_*.', 'Собранную статистику планировщика смотрят в pg_stats и pg_stats_ext.'),
        ('option', 'Запрос отбирает строки по city и zip одновременно. Значения столбцов связаны, а оценка числа строк неверна. Что сделает CREATE STATISTICS для этих столбцов?', 'Объявить расширенную статистику по столбцам', 'Объявит расширенную статистику по столбцам', NULL, NULL),
        ('option', 'Запрос отбирает строки по city и zip одновременно. Значения столбцов связаны, а оценка числа строк неверна. Что сделает CREATE STATISTICS для этих столбцов?', 'Включить сбор обычной статистики для таблицы', 'Включит сбор обычной статистики для таблицы', NULL, NULL),
        ('option', 'Запрос отбирает строки по city и zip одновременно. Значения столбцов связаны, а оценка числа строк неверна. Что сделает CREATE STATISTICS для этих столбцов?', 'Сбросить накопительную статистику таблицы', 'Сбросит накопительную статистику таблицы', NULL, NULL),
        ('explanation', 'Запрос отбирает строки по city и zip одновременно. Значения столбцов связаны, а оценка числа строк неверна. Что сделает CREATE STATISTICS для этих столбцов?', NULL, NULL, 'CREATE STATISTICS объявляет объект расширенной статистики, например для зависимости значений нескольких столбцов; данные для него затем собирает ANALYZE.', 'Команда создаёт объект расширенной статистики. Для его заполнения нужен последующий ANALYZE.'),
        ('explanation', 'В addresses каждый zip соответствует одному city. Запрос фильтрует оба столбца равенствами константам, а планировщик занижает число строк. Допишите вид статистики для этой зависимости; затем будет выполнен ANALYZE:
```
CREATE STATISTICS addr_stats (___) ON city, zip FROM addresses;
```', NULL, NULL, 'Вид dependencies собирает сведения о функциональных зависимостях столбцов, чтобы планировщик не считал связанные условия независимыми.', 'dependencies описывает функциональные зависимости и помогает оценивать связанные условия равенства столбцов константам. Данные собирает ANALYZE. Порядок city, zip в объявлении не задаёт направление зависимости.'),
        ('option', 'В дочернюю таблицу вставляют строку со ссылкой на родительскую. В каком режиме проверка внешнего ключа блокирует родительскую строку?', 'FOR KEY SHARE', NULL, 'Проверке нужно лишь, чтобы строка и её ключ не исчезли до конца транзакции.', 'Проверка защищает найденную родительскую строку и её ключ от удаления и изменения, пока удерживается блокировка.'),
        ('explanation', 'В дочернюю таблицу вставляют строку со ссылкой на родительскую. В каком режиме проверка внешнего ключа блокирует родительскую строку?', NULL, NULL, 'Проверка внешнего ключа выполняет для родительской строки запрос с FOR KEY SHARE. До конца транзакции другие транзакции не могут удалить эту строку или изменить её ключ, но неключевые столбцы менять могут. Для отложенного внешнего ключа блокировка появляется в момент проверки, а не при вставке.', 'Проверка внешнего ключа выполняет для родительской строки запрос с FOR KEY SHARE. Пока эта блокировка удерживается, другие транзакции не могут удалить строку или изменить её ключ, но неключевые столбцы менять могут. Для отложенного внешнего ключа блокировка появляется в момент проверки, а не при вставке.'),
        ('option', 'В t первичный ключ id, других уникальных индексов нет. A прочитала строку с FOR SHARE и осталась открытой. B обновляет её неключевой столбец. Чем ситуация отличается от случая, когда A использует FOR KEY SHARE?', 'FOR SHARE не даёт менять и неключевые столбцы', 'FOR SHARE блокирует и UPDATE неключевого столбца', NULL, NULL),
        ('option', 'В t первичный ключ id, других уникальных индексов нет. A прочитала строку с FOR SHARE и осталась открытой. B обновляет её неключевой столбец. Чем ситуация отличается от случая, когда A использует FOR KEY SHARE?', 'FOR KEY SHARE не мешает удалить эту строку', 'FOR KEY SHARE разрешает DELETE защищённой строки', 'Мешает: DELETE берёт FOR UPDATE, а с ним FOR KEY SHARE несовместим.', 'Не разрешает: DELETE берёт FOR UPDATE, а с ним FOR KEY SHARE несовместим.'),
        ('option', 'В t первичный ключ id, других уникальных индексов нет. A прочитала строку с FOR SHARE и осталась открытой. B обновляет её неключевой столбец. Чем ситуация отличается от случая, когда A использует FOR KEY SHARE?', 'FOR KEY SHARE ждёт завершения чужого FOR SHARE', 'FOR KEY SHARE конфликтует с режимом FOR SHARE', 'Не ждёт: эти режимы совместимы.', 'Не конфликтует: эти режимы совместимы.'),
        ('option', 'В t первичный ключ id, других уникальных индексов нет. A прочитала строку с FOR SHARE и осталась открытой. B обновляет её неключевой столбец. Чем ситуация отличается от случая, когда A использует FOR KEY SHARE?', 'FOR SHARE несовместим с другим FOR SHARE', 'FOR SHARE конфликтует с другим режимом FOR SHARE', 'Совместим: несколько транзакций могут одновременно держать FOR SHARE на одной строке.', 'Не конфликтует: несколько транзакций могут одновременно держать FOR SHARE на одной строке.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
